begin;

-- Seed public.meal_templates from the curated catalog that used to be compiled
-- into the app bundle (src/data/mealTemplates.ts).
--
-- Recommended meals are chosen by deterministic filtering and ranking, never by
-- a language model, so this table is the whole source of truth for what can be
-- recommended. Moving it out of the bundle means the catalog can be corrected,
-- extended or re-tagged without shipping a build.
--
-- ingredient_blueprint holds the app's own food ids rather than public.foods
-- uuids: portions are scaled and scored on-device against bundled nutrition
-- data, so a recommendation costs one query and no per-ingredient lookups.
--
-- Idempotent: re-running updates in place, keyed on slug.

insert into public.meal_templates (
  slug, name, description, prep_minutes,
  instructions, dietary_tags, allergens, activity_types,
  ideal_timing_minutes, timing_low_minutes, timing_high_minutes, min_workout_minutes,
  ingredient_blueprint, is_verified
) values
